<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); $service = app(App\Services\SleekflowService::class); $service->syncContacts('2026-05-01', '2026-05-16'); echo json_encode(App\Models\SleekflowContact::whereBetween('created_at_sleekflow', ['2026-04-30 00:00:00', '2026-05-17 23:59:59'])->where('contact_owner_name', 'like', '%Ferdian%')->where(function($q) { $q->whereNull('status_chat')->orWhere('status_chat', '')->orWhere('status_chat', 'Contact Filtered'); })->selectRaw('status_chat, COUNT(*) as count')->groupBy('status_chat')->get());
